{
  "outcome": "deny",
  "rationale": "We are denying this claim because the claimant admitted the damage was caused by long-term deterioration and age rather than the reported collision. Under Section 2.1, coverage is limited to direct and accidental loss caused by collision. The claimant's account explicitly states the panels had been rusting and cracking from age for years.",
  "citations": [
    {
      "clause_id": "BASIC-2.1",
      "quote": "we will pay for direct and accidental loss to the covered vehicle caused by collision during the policy period."
    }
  ]
}
